#include "ir_helpers.h"
#include "optimizer_call_internal.h"

#include <stdio.h>
#include <string.h>

/**
 * @brief Translate a source slot ID into its cloned parameter or local slot ID.
 *
 * @param slot Stack slot to remap or write.
 * @param offset Offset added to an ID that is outside any parameter mapping.
 * @param parameters Mapping for source parameter slots.
 * @param parameter_count Number of source slots covered by the map.
 * @return Slot ID in the destination function.
 */
static IrStackSlotId remap_slot(IrStackSlotId slot,
                                size_t offset,
                                const IrStackSlotId* parameters,
                                size_t parameter_count) {
  return slot < parameter_count ? parameters[slot] : offset + slot;
}

void optimizer_call_remap_value(IrOperand* operand, size_t offset) {
  if (operand->type == IR_OP_VALUE)
    operand->value.id += offset;
}

void optimizer_clone_instruction(Ctx* ctx,
                                 IrFunctionId destination,
                                 IrBlockId bid,
                                 IrInstruction old,
                                 size_t value_offset,
                                 size_t slot_offset,
                                 const IrStackSlotId* parameters,
                                 size_t parameter_count) {
  ir_add_instruction(ctx, destination, bid, old);

  IrInstructionArray* instructions =
      &ctx->ir.functions.data[destination].blocks.data[bid].instructions;

  IrInstruction* inst = &instructions->data[instructions->count - 1];

  inst->result =
      old.result == IR_INVALID_ID ? IR_INVALID_ID : old.result + value_offset;

  switch (ir_get_instruction_class(inst)) {
    case IR_INST_CLASS_UNARY:
      optimizer_call_remap_value(&inst->operands.unary.operand, value_offset);
      break;

    case IR_INST_CLASS_BINARY:
      optimizer_call_remap_value(&inst->operands.binary.left, value_offset);
      optimizer_call_remap_value(&inst->operands.binary.right, value_offset);
      break;

    case IR_INST_CLASS_LOAD:
      inst->operands.load.source = remap_slot(
          inst->operands.load.source, slot_offset, parameters, parameter_count);
      break;

    case IR_INST_CLASS_STORE:
      inst->operands.store.target =
          remap_slot(inst->operands.store.target, slot_offset, parameters,
                     parameter_count);

      optimizer_call_remap_value(&inst->operands.store.source, value_offset);
      break;

    case IR_INST_CLASS_CALL:
      for (size_t i = 0; i < inst->operands.call.arg_count; i++)
        optimizer_call_remap_value(&inst->operands.call.args[i], value_offset);
      break;
  }
}

void optimizer_call_emit_argument_store(Ctx* ctx,
                                        IrFunctionId fid,
                                        IrBlockId bid,
                                        IrStackSlotId slot,
                                        IrOperand value) {
  ir_add_instruction(
      ctx, fid, bid,
      (IrInstruction){.type = IR_INST_STORE,
                      .operands.store = {.source = value, .target = slot}});
}

IrBlockTerminator optimizer_call_jump_to(IrBlockId block) {
  return (IrBlockTerminator){.type = IR_TERMINATOR_JUMP,
                             .value.jump_target = block};
}
